glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
uniform sampler2D expressionTexture;
layout(std140) uniform IllustrationIdle { vec4 frameRect; vec4 idleMotion; vec4 idleShape; vec4 idleDetail; vec4 idleSecondary; vec4 faceEyes; vec4 faceMouth; vec4 eyePatch; vec4 mouthPatch; vec4 faceExpression; vec4 rasterSize; vec4 idleJoints; vec4 idleArm; vec4 idleWrist; vec4 idlePose; };
vec4 expressionPatch(vec4 base,vec2 point,vec4 target,vec4 source,float strength) {
  vec2 q=(point-target.xy)*rasterSize.xy;
  float c=cos(faceExpression.x),s=sin(faceExpression.x);
