  vec2 ellipse=(q-vec2(0.5))*2.0;
  float weight=(1.0-smoothstep(0.62,1.0,dot(ellipse,ellipse)))*strength*faceExpression.w;
  vec4 feature=texture(expressionTexture,source.xy+clamp(q,vec2(0.001),vec2(0.999))*source.zw);
