vec2 inverseJoint(vec2 p,vec2 pivot,float angle) {
  vec2 q=(p-pivot)*rasterSize.xy;float c=cos(angle),s=sin(angle);
  return pivot+vec2(c*q.x+s*q.y,-s*q.x+c*q.y)/rasterSize.xy;
