float capsule(vec2 p,vec2 a,vec2 b,float radius) {
  vec2 ratio=vec2(rasterSize.x/rasterSize.y,1.0),ap=(p-a)*ratio,ab=(b-a)*ratio;
  float t=clamp(dot(ap,ab)/max(dot(ab,ab),0.00001),0.0,1.0);
