  p=inverseJoint(p,idleJoints.zw,idlePose.x*upper);
  p.y+=idleMotion.x*(1.0-smoothstep(0.32,0.66,p.y));
  float armWeight=max(capsule(p,idleArm.xy,idleArm.zw,idleWrist.z),capsule(p,idleArm.zw,idleWrist.xy,idleWrist.z));
  p=inverseJoint(p,idleArm.xy,idlePose.z*idleWrist.w*armWeight*smoothstep(idleJoints.y-0.02,idleJoints.y+0.08,p.y));
  float forearmWeight=capsule(p,idleArm.zw,idleWrist.xy,idleWrist.z);
  p=inverseJoint(p,idleArm.zw,idlePose.w*idleWrist.w*forearmWeight*smoothstep(idleJoints.y-0.02,idleJoints.y+0.08,p.y));
  float head=(1.0-smoothstep(idleJoints.y-0.012,idleJoints.y+0.055,p.y));
  p=inverseJoint(p,idleJoints.xy,idlePose.y*head);
  p.y+=idleSecondary.x*head;
