  float hair=side*smoothstep(idleJoints.y-.035,idleJoints.y+.09,p.y)*(1.0-smoothstep(idleShape.w-.1,idleShape.w,p.y));
  p.x+=idleMotion.z*hair;
  float cloth=exp(-pow((p.y-idleDetail.y)*13.0,2.0))*smoothstep(0.08,0.25,abs(p.x-.5))*upper;
  p.x+=idleMotion.w*cloth;
  float inside=step(0.0,p.x)*step(p.x,1.0)*step(0.0,p.y)*step(p.y,1.0);
  p=clamp(p,idleDetail.zw,vec2(1.0)-idleDetail.zw);
  vec4 o=CCSampleWithAlphaSeparated(cc_spriteTexture,frameRect.xy+p*frameRect.zw);
  o=expressionPatch(o,p,faceEyes,eyePatch,faceExpression.y);
  o=expressionPatch(o,p,faceMouth,mouthPatch,faceExpression.z);
